def read(p):return json.loads(p.read_text())
def dump(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2,sort_keys=True)+'\n')
def test_body(p,name):
    name=name.split('[')[0];s=p.read_text();tree=ast.parse(s)
    for n in ast.walk(tree):
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==name:
            return dict(path=str(p.relative_to(ROOT)),line=n.lineno,source=ast.get_source_segment(s,n),assertions=[ast.get_source_segment(s,x) for x in ast.walk(n) if isinstance(x,ast.Assert)])
    raise AssertionError((p,name))
def junit_failure(suite,name,epoch):
    for c in ET.parse(G15/'execution'/epoch/(suite+'.xml')).iter('testcase'):
        if c.get('name')==name:
            f=c.find('failure');return None if f is None else dict(message=f.get('message'),text=f.text)
    raise AssertionError((suite,name))
