            if actual['candidate'][cid]['observed_state'].get('status')=='LEGACY_HANDLER_NOT_EVALUABLE':row['predicate_evaluation']='NOT_EVALUABLE_GROUP_NOT_INDIVIDUAL_FALSE_PROPOSITIONS'
