    md=['# Independent adjudication of all 56 newly failing inherited pytest cases','','Every row is PASS on the exact G13 baseline and literal RED on G15. No waiver or oracle edit. Full assertions, original handler bodies, before/after outputs, original blobs and actual failure text are in `02_COMPATIBILITY_56.json`. Related rows share a mechanism; they are not independent discoveries.','', '| # | Exact inherited ID | Classification | Scientific disposition / alternative |','|---|---|---|---|']
    for i,c in enumerate(cases,1):md.append('| '+str(i)+' | `'+c['exact_pytest_id']+'` | '+c['classification']+' | '+c['scientific_meaning'].replace('|','/')+' Alternative: '+c['alternative']+'; '+c['alternative_grade']+'. |')
    (ROOT/'02_COMPATIBILITY_56.md').write_text('\n'.join(md)+'\n')
    print('56 cases adjudicated; 17 original REDs preserved; 9 unavailable groups individually covered')
